def list_001_sum(xs):
    sum = 0
    for i in xs:
        sum = (sum + i)
    return sum

def list_002_length(xs):
    n = len(xs)
    dp = [0 for i in range(n)]
    dp[(n - 1)] = 1
    for i in range((n - 2), (-1), (-1)):
        mxm = 0
        for j in range((i + 1), n):
            if (((xs[j] % xs[i]) == 0) if ((xs[j] % xs[i]) == 0) else ((xs[i] % xs[j]) >= 0)):
                mxm = max(mxm, dp[j])
        dp[i] = (1 + mxm)
    return max(dp)
